package com.eljefe.interviews;
import android.app.*; import android.content.*; import android.net.Uri; import android.os.*; import android.provider.MediaStore; import android.graphics.Color; import android.view.Gravity; import android.widget.*; import java.util.*;
public class MainActivity extends Activity {
 int pink=Color.rgb(255,20,147), dark=Color.rgb(5,5,10), white=Color.WHITE; Uri lastVideo; ArrayList<String> qs=new ArrayList<>();
 LinearLayout content;
 public void onCreate(Bundle b){super.onCreate(b);qs.add("¿Cómo valoras la temporada?");qs.add("¿Qué objetivos tiene el equipo?");qs.add("¿Qué mensaje mandas a la afición?");home();}
 TextView label(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER);t.setPadding(8,12,8,12);return t;}
 void init(String title){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,20,16,16);root.setBackgroundColor(dark);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(1);sc.addView(content);root.addView(sc);setContentView(root);TextView h=label(title,26,pink);h.setTypeface(null,1);content.addView(h);}
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(white);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(pink));b.setOnClickListener(v->r.run());content.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 void msg(String s){new AlertDialog.Builder(this).setTitle("EL JEFE 5.0").setMessage(s).setPositiveButton("Aceptar",null).show();}
 void home(){init("👑 EL JEFE 5.0\nENTREVISTAS FÚTBOL");content.addView(label("C.D. SANTA ANA · NEGRO Y FUCSIA",14,white));btn("🎙 GRABAR ENTREVISTA (VÍDEO + AUDIO)",()->{try{startActivityForResult(new Intent(MediaStore.ACTION_VIDEO_CAPTURE),50);}catch(Exception e){msg("No se pudo abrir la cámara.");}});btn("✂ RECORTAR AUDIO",()->msg("Abre una grabación en un editor compatible para recortarla. Herramienta integrada pendiente."));btn("🔊 MEJORAR VOZ Y REDUCIR RUIDO",()->msg("La mejora avanzada de voz requiere un módulo de procesamiento adicional; no está implementado aún."));btn("📋 PREGUNTAS PREPARADAS",()->questions());btn("📁 ARCHIVO DE ENTREVISTAS",()->archive());btn("⚙ AJUSTES",()->{init("AJUSTES");content.addView(label("EL JEFE 5.0 · Entrevistas de fútbol",16,white));btn("VOLVER",()->home());});}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==50&&c==RESULT_OK&&d!=null){lastVideo=d.getData();msg("Entrevista grabada. La cámara puede guardarla en la galería del móvil.");}}
 void archive(){init("📁 MIS ENTREVISTAS");btn("▶ REPRODUCIR ÚLTIMA GRABACIÓN",()->{if(lastVideo==null){msg("Graba primero una entrevista. Consulta también la galería del móvil.");return;}Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(lastVideo,"video/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);});btn("↗ COMPARTIR ÚLTIMA GRABACIÓN",()->{if(lastVideo==null){msg("Graba primero una entrevista.");return;}Intent i=new Intent(Intent.ACTION_SEND);i.setType("video/*");i.putExtra(Intent.EXTRA_STREAM,lastVideo);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Compartir entrevista"));});btn("VOLVER",()->home());}
 void questions(){init("📋 PREGUNTAS PREPARADAS");for(String q:qs)content.addView(label("• "+q,17,white));btn("＋ AÑADIR PREGUNTA",()->{EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("Nueva pregunta").setView(e).setPositiveButton("Guardar",(d,w)->{if(e.length()>0)qs.add(e.getText().toString());questions();}).setNegativeButton("Cancelar",null).show();});btn("VOLVER",()->home());}
}
